for n in ['ALL-457-MODULES.tsv','SOURCE-OWNERSHIP.tsv','evidence/audit-summary.json','evidence/workspace-baseline.json']:(E/Path(n).name).write_bytes((A/n).read_bytes())
(E/'selected-original-rows.json').write_text(json.dumps(selected,indent=2)+'\n')
with (P/'DEPENDENCIES.tsv').open('w') as o:
 w=csv.DictWriter(o,fieldnames=list(edges[0]),delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(edges)
h=hashlib.sha256((P/'BATCH-MANIFEST.tsv').read_bytes()).hexdigest();(P/'BATCH-MANIFEST.sha256').write_text(h+'  BATCH-MANIFEST.tsv\n');head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip();pins=json.loads((H/'BATCH-STATE.json').read_text())['source_pins']
state={'schema':3,'phase':'MANIFEST_FROZEN_NOT_COMPILED','baseline_research_commit':head,'baseline_certified':187,'baseline_uncertified':271,'manifest_sha256':h,'selected_count':34,'families':families,'repositories':repos,'source_pins':pins,'completed_modules':[],'pending_modules':names,'blocked_modules':{},'current_module':None,'build_directories':{'development':'/home/armol/kernel-work/platform-batch-03-dev','cleancheck':'/home/armol/kernel-work/platform-batch-03-cleancheck','immutable_mirror':'/home/armol/kernel-work/interconnect-pin-mirror'},'latest_parity_result':'Not compiled; canonical validator zero errors','independent_validation_status':'NOT_STARTED','relevant_commits':{'baseline_research':head},'next_immediate_action':'Recover six G historical implementations, preserve mt6375 delta; assemble genuine joint34 and source provider units','safety':'Strict offline; local commits only; no phone or push'};(P/'BATCH-STATE.json').write_text(json.dumps(state,indent=2)+'\n')
print('FROZEN34',h,'imports',len(edges),'classes28D6G; proposal unchanged')
